CREATE OR REPLACE FUNCTION public.rpc_settlements(p_world uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid();
begin
  perform private.pace(auth.uid(), 'act');
